import express from "express";
import path from "path";
import { fileURLToPath } from "url";
import { createServer as createViteServer } from "vite";
import { Resend } from "resend";
import { GoogleGenAI, Type } from "@google/genai";
import dotenv from "dotenv";
import cors from "cors";

dotenv.config();

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

async function startServer() {
  const app = express();
  const PORT = 3000;

  app.use(cors()); // Allow all origins
  app.use((req, res, next) => {
    res.setHeader("Cross-Origin-Opener-Policy", "unsafe-none");
    res.setHeader("Cross-Origin-Embedder-Policy", "unsafe-none");
    next();
  });
  app.use(express.json({ limit: '50mb' }));

  app.get("/api/health", (req, res) => {
    res.json({ 
      status: "ok", 
      env: {
        hasGemini: !!process.env.GEMINI_API_KEY,
        hasResend: !!process.env.RESEND_API_KEY
      }
    });
  });

  const resend = process.env.RESEND_API_KEY ? new Resend(process.env.RESEND_API_KEY) : null;
  const ai = process.env.GEMINI_API_KEY ? new GoogleGenAI({ 
    apiKey: process.env.GEMINI_API_KEY,
    httpOptions: {
      headers: {
        'User-Agent': 'aistudio-build',
      }
    }
  }) : null;

  // API Routes
  app.get("/api/ai/health", (req, res) => {
    res.json({ 
      configured: !!ai,
      model: "gemini-3-flash-preview"
    });
  });

  app.post("/api/ai/extract", async (req, res) => {
    if (!ai) {
      console.error("Gemini API key missing in environment");
      return res.status(500).json({ error: "Gemini API key not configured" });
    }

    try {
      const { imageBase64, mimeType } = req.body;
      console.log(`[AI Extract] Starting extraction for ${mimeType}`);
      
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: {
          parts: [
            {
              inlineData: {
                mimeType: mimeType || "image/jpeg",
                data: imageBase64
              }
            },
            { text: "Extract car details from this image. Return JSON ONLY with keys: brand, model, year, category (one of: Luxury المتميزة, عائلية SUV, اقتصادية, رياضية), pricePerDay (estimate if not visible, e.g. 1000), engine, transmission (أوتوماتيكي or يدوي), caution (estimate, e.g. 5000), description (short marketing text in Arabic)." }
          ]
        }
      });

      console.log("[AI Extract] Response received");
      const responseText = response.text;
      if (!responseText) throw new Error("Empty response from AI");

      const jsonMatch = responseText.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        return res.json(JSON.parse(jsonMatch[0]));
      }
      res.status(422).json({ error: "Could not extract structured data" });
    } catch (err: any) {
      console.error("AI Extraction Error:", err);
      res.status(500).json({ error: err.message || "Failed to process image with AI" });
    }
  });

  app.post("/api/ai/chat", async (req, res) => {
    if (!ai) return res.status(500).json({ error: "Gemini API key not configured" });

    try {
      const { messages, history } = req.body;
      console.log(`[AI Chat] Received message with ${history?.length || 0} history items`);
      
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: [
          ...(history || []),
          { role: 'user', parts: messages }
        ],
        config: {
          systemInstruction: "أنت مساعد ذكي لمدير تطبيق تأجير سيارات فخمة في المغرب. \nعند استلام صورة سيارة، قم باستخراج تفاصيلها (الماركة، الموديل، السنة، الفئة، السعر المقترح، المحرك، ناقل الحركة، الضمان، والوصف). \nاعرض هذه التفاصيل للمستخدم أولاً في رسالة واضحة ومنسقة واسأله إذا كانت صحيحة أو إذا كان يريد تعديل أي منها. \nلا تقم باستدعاء أداة addCarToDatabase أبداً إلا بعد أن يطلب منك المستخدم ذلك صراحة (مثلاً: 'أضفها'، 'تم'، 'احفظها'). \nإذا طلب المستخدم تعديل أي معلومة، قم بتحديث بياناتك واعرضها مجدداً للتأكيد. \nاجعل الوصف جذاباً وباللغة العربية.",
          tools: [{
            functionDeclarations: [{
              name: "addCarToDatabase",
              description: "Adds a new car to the rental database based on extracted details.",
              parameters: {
                type: Type.OBJECT,
                properties: {
                  brand: { type: Type.STRING },
                  model: { type: Type.STRING },
                  year: { type: Type.NUMBER },
                  category: { type: Type.STRING },
                  pricePerDay: { type: Type.NUMBER },
                  engine: { type: Type.STRING },
                  transmission: { type: Type.STRING },
                  caution: { type: Type.NUMBER },
                  description: { type: Type.STRING },
                },
                required: ["brand", "model", "year", "category", "pricePerDay", "engine", "transmission", "caution", "description"],
              },
            }]
          }]
        }
      });
      
      console.log("[AI Chat] Response received", { hasText: !!response.text, hasFunctionCalls: !!response.functionCalls });

      res.json({ 
        text: response.text, 
        functionCalls: response.functionCalls 
      });
    } catch (err: any) {
      console.error("AI Chat Error:", err);
      res.status(500).json({ error: err.message || "Failed to process chat with AI" });
    }
  });

  app.post("/api/send-confirmation-email", async (req, res) => {
    const { customerEmail, customerName, carName, startDate, endDate, bookingId } = req.body;

    if (!resend) {
      console.warn("RESEND_API_KEY is not set. Email not sent.");
      return res.status(500).json({ error: "Email service not configured" });
    }

    try {
      const { data, error } = await resend.emails.send({
        from: "TNG Drive <onboarding@resend.dev>", // Resend test sender
        to: [customerEmail],
        subject: `تأكيد حجزك - # ${bookingId.slice(0, 8)}`,
        html: `
          <div style="font-family: sans-serif; direction: rtl; text-align: right; background-color: #f4f4f4; padding: 40px;">
            <div style="max-width: 600px; margin: 0 auto; background-color: #ffffff; padding: 20px; border-radius: 8px; border-top: 4px solid #C5A059;">
              <h1 style="color: #C5A059;">تم تأكيد حجزك بنجاح!</h1>
              <p>عزيزي <strong>${customerName}</strong>،</p>
              <p>نحن سعداء بإبلاغك أن طلب حجزك قد تم تأكيده بنجاح.</p>
              
              <div style="background-color: #fafafa; padding: 15px; border-radius: 4px; margin: 20px 0;">
                <h3 style="margin-top: 0;">تفاصيل الحجز:</h3>
                <ul style="list-style: none; padding: 0;">
                  <li><strong>السيارة:</strong> ${carName}</li>
                  <li><strong>من تاريخ:</strong> ${startDate}</li>
                  <li><strong>إلى تاريخ:</strong> ${endDate}</li>
                  <li><strong>رقم الحجز:</strong> ${bookingId}</li>
                </ul>
              </div>
              
              <p>سيقوم فريقنا بالتواصل معك قريباً لترتيب استلام السيارة.</p>
              <p>شكراً لاختيارك TNG Drive!</p>
              
              <hr style="border: 0; border-top: 1px solid #eeeeee; margin: 20px 0;">
              <p style="font-size: 12px; color: #999999; text-align: center;">هذا البريد مرسل تلقائياً، يرجى عدم الرد عليه.</p>
            </div>
          </div>
        `,
      });

      if (error) {
        return res.status(400).json({ error });
      }

      res.status(200).json({ data });
    } catch (err) {
      console.error("Error sending email:", err);
      res.status(500).json({ error: "Internal server error" });
    }
  });

  // Notify Admin Route
  app.post("/api/notify-admin", async (req, res) => {
    const { customerName, customerPhone, customerEmail, carName, startDate, endDate, totalPrice } = req.body;
    const adminEmail = process.env.ADMIN_EMAIL || "tangierdrive40@gmail.com";

    if (!resend) {
      console.warn("RESEND_API_KEY is not set. Admin email not sent.");
      return res.status(500).json({ error: "Email service not configured" });
    }

    try {
      await resend.emails.send({
        from: "TNG Drive <onboarding@resend.dev>",
        to: [adminEmail],
        subject: `حجز جديد من ${customerName}`,
        html: `
          <div style="font-family: sans-serif; direction: rtl; text-align: right; padding: 20px;">
            <h2>حجز جديد تم استلامه!</h2>
            <p><strong>العميل:</strong> ${customerName}</p>
            <p><strong>الهاتف:</strong> ${customerPhone}</p>
            <p><strong>الإيميل:</strong> ${customerEmail}</p>
            <hr>
            <p><strong>السيارة:</strong> ${carName}</p>
            <p><strong>الفترة:</strong> من ${startDate} إلى ${endDate}</p>
            <p><strong>المبلغ الإجمالي:</strong> ${totalPrice} درهم</p>
          </div>
        `,
      });
      res.status(200).json({ success: true });
    } catch (err) {
      console.error("Error notifying admin:", err);
      res.status(500).json({ error: "Failed to notify admin" });
    }
  });

  // Vite middleware for development
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
